insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16ff4a51-d956-4ee9-bd1d-b820aaad519a', 'es', '¿Qué significa saber leer la situación cuando te acercas a alguien de día?', '["Ajustar tu energía a la de ella", "Adaptarte según sus señales de comodidad", "Mantener una interacción respetuosa", "Todas las anteriores"]'::jsonb, 'Saber leer la situación es atención puesta en práctica: leer su respuesta y ajustarte a ella.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17e5ea51-94a8-4084-bfd8-18b8a92f9ae9', 'es', '¿Qué es lo que rechazan las mujeres cuando alguien se les acerca de día?', '["Que un desconocido se les acerque en un lugar público", "Que un hombre interrumpa lo que está haciendo y su rutina diaria", "Que alguien muestre una intención romántica directa de día", "Acercamientos que ignoran su comodidad y el respeto"]'::jsonb, 'La incomodidad viene de que se ignoren sus límites, no de que alguien se acerque.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c7c4962-c5cf-480e-94ba-1cc03443f821', 'es', 'Ves a una mujer mirando libros en una tienda. ¿Qué forma de acercarte genera comodidad?', '["Llegar por detrás y tocarle el hombro", "Elogiar su aspecto de inmediato", "Esperar a que ella te mire primero", "Entrar en su campo de visión, sonreír con calma y saludar"]'::jsonb, 'Acercarte de forma visible y con una sonrisa transmite respeto y evita el sobresalto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f1937b7-4e35-4007-97d7-0ba51bfa30af', 'es', '¿Por qué de noche se paga más caro dudar?', '["A las mujeres se les acercan todo el tiempo, así que tienen más opciones", "En lugares caóticos la atención cambia rápido y las oportunidades desaparecen", "El alcohol vuelve a la gente más impaciente y menos tolerante", "Si no actúas rápido, otros hombres se le acercarán"]'::jsonb, 'De noche el ambiente cambia rápido, así que cada demora convierte las señales en oportunidades perdidas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c6d0086-b465-4912-9e47-4cec5bc122f2', 'es', 'Abres con calma, pero hablas bajito en un lugar con mucho ruido. ¿Qué es lo más probable?', '["Ella se inclina hacia ti", "La interacción se siente estable", "El ritmo se cae", "La atracción aumenta"]'::jsonb, 'Una energía baja que no encaja con el ambiente hace que la otra persona se desconecte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e4f60ca8-4125-463e-b6ce-3c84259813a8', 'es', 'Ella está pidiendo en la barra. Te pones a su lado para pedir. Te mira un momento. ¿Qué haces?', '["Pides tu bebida primero y le hablas cuando los dos ya tengan algo", "Esperas a ver si te da otra señal", "La saludas y empiezas a hablar con ella"]'::jsonb, 'No esperes más señales; de noche, una mirada basta para empezar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbc9b59e-d2c5-4cb0-be94-f4bc54ea2bca', 'es', '¿Cuál es el objetivo al acercarte por primera vez a un grupo?', '["Impresionar a la que te interesa para destacar entre los demás chicos", "Que todos te acepten y luego centrar tu atención en ella", "Identificar al líder del grupo y hacerte su amigo para tener su aprobación", "Aportar tanto que el grupo te invite a quedarte"]'::jsonb, 'Tener en cuenta al grupo te da permiso; incluye a todos antes de centrarte en una persona.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10add83c-809f-43e0-aa9a-31d38bfb3270', 'es', 'Un grupo se está riendo a carcajadas. Te acercas con un comentario serio y en voz baja. ¿Qué pasa?', '["El choque de energía hace que se desconecten", "Conectan contigo a fondo", "Valoran tu autenticidad", "La que te interesa te lleva aparte"]'::jsonb, 'Un choque de energía hace que se desconecten; refleja su entusiasmo para mantener el flujo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2efcf135-1220-4266-bbc1-7828bea5592d', 'es', '¿Qué cambio de mentalidad ayuda a los hombres a acercarse a grupos con éxito?', '["Ver a sus amigas como posibles aliadas, no como obstáculos", "Dar por hecho que los grupos siempre son más difíciles que una mujer sola", "Concentrarte primero solo en impresionar a la que te interesa"]'::jsonb, 'Cuando el grupo se siente tomado en cuenta, la conexión con una persona se vuelve más fácil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4756728e-4c07-484b-a976-9eeb5814eca7', 'es', 'Abres con “Tengo una pregunta para ti”. Ella levanta la vista, expectante. ¿Qué indica esto?', '["Cortesía", "Curiosidad", "Evaluación", "Rechazo"]'::jsonb, 'La curiosidad funciona porque atrae la atención de forma natural; abre con algo que intrigue.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28aa155d-35ca-4afd-abcc-bc4cb3e22a6d', 'es', '¿Por qué funciona tan bien plantear “Necesito la opinión de una mujer sobre algo”?', '["Hace que se sienta valorada e importante en la interacción", "Despierta curiosidad por saber cuál es el dilema o la pregunta", "Las dos anteriores"]'::jsonb, 'Funciona porque la presenta como alguien relevante; la hace sentirse incluida desde el principio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7aa7c045-3cd0-4ffe-aa02-400edd9bc5b7', 'es', '¿Por qué las aperturas de curiosidad enganchan más que las preguntas directas?', '["Activan el impulso del cerebro de llenar vacíos de información", "Dan respuestas concretas de inmediato", "Hacen que quiera saber qué viene después"]'::jsonb, 'La curiosidad crea una atracción psicológica más fuerte que el desinterés por defecto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f40037b2-a636-4084-a804-c553ece3de6a', 'es', '¿Qué ventaja tienen al principio las aperturas con una suposición?', '["Muestran dominancia", "La involucran al instante", "Ocultan tu intención", "Reducen el riesgo"]'::jsonb, 'Las suposiciones obligan a responder y generan participación inmediata.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3e974466-6524-42dc-a429-63bb8e831188', 'es', '¿Por qué una apertura como “Haces pilates, ¿verdad?” la involucra de inmediato?', '["Demuestra que te fijas en su condición física", "Genera participación inmediata: tiene que corregirte o confirmarlo", "Demuestra que sabes de deporte y salud"]'::jsonb, 'Las suposiciones piden una respuesta. Al instante, ella participa corrigiendo o confirmando.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1874cbce-d4aa-44b1-ab88-ff0c2745d69f', 'es', '¿Por qué las aperturas con una suposición enganchan más que las preguntas genéricas?', '["Despiertan curiosidad por cómo la percibes", "Se pueden responder en piloto automático", "Piden una confirmación o una corrección"]'::jsonb, 'Las suposiciones la hacen sentirse vista y despiertan su participación de inmediato.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e84223a-e094-4ee6-8da9-79cd89d634c7', 'es', '“Necesito la opinión de una mujer sobre algo” funciona porque:', '["despierta curiosidad por saber sobre qué necesitas una opinión", "hace que sienta que su punto de vista se valora y es importante", "presenta a las mujeres como alguien con una visión especial que necesitas", "todas las anteriores"]'::jsonb, 'Despierta curiosidad, la hace sentirse valorada y presenta la perspectiva femenina como valiosa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc959e07-994f-4a1d-b948-b437f3e6f2b2', 'es', 'Abres con un dilema. Ella te da una respuesta detallada. ¿Qué podrías hacer después?', '["Terminar la interacción", "Darle toda la razón", "Cambiar de tema", "Construir sobre lo que dijo"]'::jsonb, 'Construir sobre su respuesta premia su esfuerzo y mantiene vivo el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c800f82-c80b-490c-988f-e66f6100d311', 'es', '¿Qué aperturas valoran su perspectiva?', '["“Necesito la opinión de una mujer”", "“Una pregunta rápida”", "“Eres muy atractiva”", "“Mi amigo y yo estábamos discutiendo algo”"]'::jsonb, 'Estas aperturas la presentan como alguien relevante; la hacen sentirse incluida desde el principio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43b03548-630d-4716-8d45-71c89fa4a819', 'es', '¿Qué es un límite de tiempo cuando te acercas a alguien?', '["Un plazo que le das para responder a tu acercamiento", "Una técnica para crear urgencia y escasez en la interacción", "Una frase inicial que indica que te vas a ir pronto"]'::jsonb, 'Decir que no te vas a quedar mucho rato quita presión; úsalo al principio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfb43838-50ce-4ae4-8c8a-722afd35d73a', 'es', '¿Cuál es el objetivo de poner un límite de tiempo al acercarte?', '["Controlar la interacción presentándote como alguien ocupado", "Crear escasez para que valore más tu tiempo limitado", "Que ella esté cómoda, sin la presión de algo que no se sabe cuándo termina"]'::jsonb, 'Decir que no te vas a quedar mucho rato quita presión; úsalo al principio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66801814-05f0-417d-a387-606cb86e6cf9', 'es', 'Te acercas a una mujer en una cafetería. ¿Qué puedes decir primero para quitar presión?', '["Elogiar su aspecto de inmediato", "Decir que solo te puedes quedar un segundo", "Hacerle preguntas personales profundas", "Proponer ir a otro lugar"]'::jsonb, 'Un límite de tiempo indica que te irás pronto, y eso hace que baje la guardia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8993be7c-90eb-4430-96e6-83d657f55add', 'es', '¿Qué señales indican que es momento de una falsa salida?', '["La energía está en su punto más alto: se ríe y está muy metida en la conversación", "La conversación acaba de empezar y todavía están creando confianza", "Sientes que la energía está a punto de estancarse o de bajar sola", "Llevan hablando exactamente 10 minutos, sin importar la energía"]'::jsonb, 'El momento justo es con la energía en lo más alto o cuando notas que se va a estancar. No se trata de marcas de tiempo arbitrarias.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6866bb5-1e8c-4c24-9fa6-7ea784314163', 'es', '¿Qué logra una falsa salida?', '["Crea un vacío al irte antes de que la conversación termine sola", "Demuestra abundancia: no necesitas exprimir cada segundo", "Evita que caigas en buscar su aprobación", "Garantiza que más tarde seguro querrá seguir"]'::jsonb, 'Crear un vacío, transmitir abundancia y no buscar aprobación: esos son los beneficios de una falsa salida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d51f94a-3406-49fb-98ed-99beb074d2bf', 'es', '“Esto estuvo divertido. Voy a saludar a más gente. Te busco luego.” Y te vas. ¿Qué lograste?', '["El riesgo de que pierda el interés o conozca a otro mientras no estás", "Una buena impresión sin terminar y curiosidad por si vuelves", "Confusión sobre si de verdad te interesa", "Demostrar que no estás del todo decidido a conquistarla"]'::jsonb, 'Irte en el mejor momento deja un buen recuerdo y un vacío de curiosidad. Se queda con ganas de más.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30461b26-dac7-40f7-ae3f-bc7f90b1ebcb', 'es', '¿Qué diferencia hay entre no acercarte y que te rechacen?', '["El rechazo duele más en el momento", "No acercarte protege tu ego y tu seguridad", "El rechazo te da experiencia; no acercarte no te da nada"]'::jsonb, 'En los dos casos no hay conexión, pero el rechazo te da experiencia para los próximos acercamientos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46975d8e-4143-4ea5-9c92-bde52c3bebad', 'es', '¿Cuál es el peor resultado cuando te planteas acercarte?', '["Un rechazo amable", "Una conversación corta que no funcionó", "Arrepentirte de no haber hecho nada", "Un silencio incómodo"]'::jsonb, 'El arrepentimiento por las oportunidades perdidas dura más que un rechazo breve.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('05af8c26-1d5f-4746-bd8d-93ffa9ceb943', 'es', '¿Por qué un rechazo es mejor que no acercarte?', '["Garantiza un arrepentimiento duradero", "Te da experiencia e información", "Abre la posibilidad de conectar", "Elimina toda incertidumbre"]'::jsonb, 'Actuar abre puertas; no actuar las cierra con total seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3400a772-93ac-48a3-a167-060ae3d525d8', 'es', '¿Con qué empiezan casi todas las conexiones en la vida?', '["Intereses en común", "El momento adecuado", "Seguridad en uno mismo", "Que alguien hable primero"]'::jsonb, 'Toda conexión empieza porque alguien da el primer paso y habla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf5ff661-2958-4e0d-ab57-b3ef0436b379', 'es', 'Estás en la fiesta de un amigo y no conoces a casi nadie. ¿Qué podrías hacer primero?', '["Quedarte callado en una esquina hasta que alguien se acerque", "Preguntarle a alguien de qué conoce al anfitrión", "Esperar a que se te ocurra la frase perfecta", "Irte temprano para evitar momentos incómodos"]'::jsonb, 'Hablar primero crea oportunidades; el silencio no crea ninguna.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('833fb7a5-48fa-44ca-bb33-3134723fc718', 'es', '¿A qué puede llevarte abrir la boca?', '["Nuevas amistades", "Nuevas experiencias", "Éxito garantizado", "Oportunidades inesperadas"]'::jsonb, 'Participar te da acceso a resultados de todo tipo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('588b3d53-613d-4e21-bdeb-77f6157427c7', 'es', '¿Por qué deberías acercarte con curiosidad y no con una intención oculta?', '["La curiosidad es más discreta; la intención oculta, más segura", "La curiosidad evita la atracción; la intención oculta la crea", "La curiosidad descubre quién es ella; la intención oculta busca un resultado"]'::jsonb, 'La curiosidad explora a la persona. Una intención oculta intenta sacar un resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4003461a-b8aa-4eaa-b66f-3d5847986f38', 'es', 'Ves que su laptop tiene calcomanías de Islandia. ¿Qué apertura muestra curiosidad genuina?', '["“Hola, me pareciste guapa y quería conocerte.”", "“¿Te puedo invitar a un café?”", "“Pareces alguien que viaja mucho.”", "“¿Esa calcomanía es de Islandia? Yo fui el año pasado.”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d398047f-31f2-46cb-991f-abb7e05f231d', 'es', '¿Por qué acercarte con curiosidad crea vínculos más fuertes que acercarte con una intención oculta?', '["La trata como una meta que alcanzar", "Hace que se sienta interesante y vista", "Quita la presión de sacar un resultado", "Permite una conversación más fluida y auténtica"]'::jsonb, 'La curiosidad se centra en ella como persona y favorece una conexión natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7265d45c-cbbc-4d5e-8220-2d1c5fe793f2', 'es', '¿Por qué acercarte se siente más difícil cuando lo haces pocas veces?', '["Sientes que hay más en juego", "Hay menos posibilidades de éxito", "El momento es peor", "El miedo aumenta"]'::jsonb, 'Cuando te acercas pocas veces, cada acercamiento pesa más y se siente más intenso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31e5395b-0177-4703-8182-44c9921a16fc', 'es', '¿Qué error hace que la gente se acerque menos de lo que podría?', '["Estar en lugares poco adecuados", "Esperar las condiciones ideales", "Estar con el celular", "Falta de interés"]'::jsonb, 'Esperar las condiciones perfectas reduce tus oportunidades. Puedes acercarte en cualquier momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b04aa8-e3ca-474a-af0c-4aac0238c9b5', 'es', '¿Qué hábitos te mantienen en contacto social con regularidad?', '["Hablar con desconocidos a lo largo de tu día normal", "Ver cualquier lugar como un sitio para practicar la conexión", "Acercarte solo cuando te sientes completamente seguro"]'::jsonb, 'Participar con regularidad baja la presión y hace que las interacciones se sientan más fáciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cd29e03-754c-4a91-8b5a-132fe680704d', 'es', '¿Para qué sirve la regla de los tres segundos?', '["Para crear urgencia", "Para evitar el rechazo", "Para perfeccionar tus aperturas", "Para actuar antes de que crezca la resistencia"]'::jsonb, 'Actuar rápido impide que la duda crezca. Muévete en los tres segundos después de verla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71a2b057-c0c3-49ae-a552-62426201f6c9', 'es', '¿Por qué esperar hace más difícil acercarte?', '["El miedo se multiplica", "La energía baja", "El interés se desvanece", "La atención se dispersa"]'::jsonb, 'El miedo crece cuando la mente tiene tiempo de imaginar resultados. Muévete rápido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8119be9-b1ef-4a0d-ab94-b3b7fdcf7ef2', 'es', 'Ves a una mujer atractiva en un bar y quieres acercarte. ¿Qué deberías hacer?', '["Empezar a planear la frase de apertura perfecta", "Pensar primero en los riesgos de un rechazo", "Ir hacia ella en menos de tres segundos", "Quedarte quieto hasta no tener miedo"]'::jsonb, 'Actúa antes de que el análisis genere resistencia y dudas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50b60dd8-f15e-4fdb-bbb1-8651ce23d2c0', 'es', '¿Por qué bloquearle el paso y el movimiento la incomoda?', '["Activa respuestas automáticas de amenaza", "Se siente grosero", "Muestra dominancia"]'::jsonb, 'El cuerpo reacciona a la falta de espacio antes que el pensamiento consciente. Dale espacio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eddec612-c258-4098-80cf-80aed2555258', 'es', 'Te acercas y notas que ella no se puede mover con facilidad. ¿Cuál es el mejor ajuste?', '["Dar un paso atrás y dejarle espacio", "Hablar más rápido", "Hacerle un cumplido"]'::jsonb, 'Dar espacio a la gente mantiene su sistema nervioso relajado y receptivo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aea4811b-264d-435b-ab0a-4bcab3bc274a', 'es', '¿Qué decisiones favorecen un acercamiento cómodo?', '["Mantenerte a la vista", "Bloquear las salidas", "Ponerte demasiado cerca", "Dejarle espacio para moverse"]'::jsonb, 'Estar a la vista y dejar espacio mantiene su sistema nervioso relajado y receptivo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2e5b5d64-e126-4877-9449-ad662c2d047e', 'es', '¿Qué transmite un cuerpo relajado en movimiento antes de que hables?', '["Seguridad, comodidad y que no eres una amenaza", "Una presencia que pide perdón o que intimida", "Necesidad de validación inmediata", "Desinterés por el entorno"]'::jsonb, 'Un movimiento fluido y abierto te da, sin que ella lo note, un buen punto de partida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e26bd7a-b3cd-4d6e-af6b-4122066f80b5', 'es', 'Caminas hacia ella con pasos bruscos y dudosos. ¿Cuál es la mejor jugada?', '["Bajar el ritmo, relajar los hombros y estabilizarte antes de acortar la distancia", "Detenerte donde estás y llamarla desde ahí", "Seguir moviéndote igual para mostrar autenticidad y honestidad"]'::jsonb, 'Moverte relajado transmite que no hay peligro y le hace más fácil la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bdb5e4d4-24f8-4710-a0ac-91194b2f10a8', 'es', '¿Qué movimientos reducen la incomodidad mientras te acercas?', '["Un ritmo constante", "Una mirada atenta pero casual", "Los hombros rígidos", "Una postura erguida"]'::jsonb, 'Moverte relajado transmite que no hay peligro y le hace más fácil la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bc72d1b-23c3-4183-b696-a4c0d69085b0', 'es', '¿Por qué ayuda una pequeña sonrisa con contacto visual antes de acercarte?', '["Transmite una intención amistosa y le da tiempo de ver que no hay peligro", "Genera atracción incluso antes de que le hayas hablado", "Crea expectativa y hace que se involucre más"]'::jsonb, 'Una pequeña sonrisa transmite simpatía, y el contacto visual le permite registrarte con calma.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48a8252e-7d72-4d16-ac74-c694f14bde94', 'es', 'Cruzan miradas desde el otro lado del lugar. Ella aparta la vista rápido. ¿Cuál es la mejor reacción?', '["Acercarte igual; apartar la vista rápido suele ser automático, no un rechazo", "Esperar a que vuelva a mirarte antes de acercarte, para confirmar su interés", "No acercarte, porque ya mostró claramente que no le interesas"]'::jsonb, 'Apartar la vista rápido suele ser automático, no un rechazo consciente. Acércate de todos modos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('42ba6d8b-fdaa-43b8-8fda-ad92c655df6e', 'es', '¿Por qué un contacto visual cálido desde antes mejora la primera impresión?', '["La toma por sorpresa para causar más impacto", "Le da tiempo de hacer una primera evaluación de seguridad", "Evita el sobresalto que la pondría a la defensiva", "Comunica una intención amistosa antes de que llegues"]'::jsonb, 'Hacerte visible y mostrar calidez hace que el acercamiento se sienta seguro, no brusco.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cbb1c37-1c29-4754-8d5f-f95600cf8b0a', 'es', '¿Por qué las aperturas indirectas le quitan presión a ella?', '["Se sienten como una conversación normal", "Evitan la atracción", "Hacen más fácil que te encuentre atractivo"]'::jsonb, 'Las aperturas indirectas se sienten normales y naturales, y eso baja la presión para los dos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d2e1560-b720-4464-8836-db55cf007d4a', 'es', 'Estás sentado junto a ella en una cafetería. ¿Qué apertura indirecta puedes usar?', '["Preguntarle si ya había venido y qué le recomienda", "Elogiar su aspecto", "Preguntarle si está soltera"]'::jsonb, 'Las aperturas indirectas se sienten normales y naturales, y eso baja la presión para los dos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5033dee2-a2a9-45d9-b214-0035a1ff5a9f', 'es', 'Los dos esperan un tren que viene con retraso. ¿Qué aperturas indirectas podrías usar?', '["Elogiar algo que lleva puesto", "Preguntarle si sabe cuándo llega el tren", "Presentarte y preguntarle su nombre", "Comentar algo sobre el retraso"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73629f15-ce28-4413-a2af-85b0b03c1ef2', 'es', '¿Qué es una apertura directa?', '["Empezar con una conversación ligera para ver si está cómoda", "Usar una charla casual neutra para crear confianza", "Decir claramente desde el principio que te atrae o que tienes una intención romántica"]'::jsonb, 'Las aperturas directas eliminan la ambigüedad porque dicen tu intención desde el principio. Ella sabe por qué estás ahí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('adb1f5a5-29e7-4c3b-88a1-33da91269c81', 'es', 'La ves en un bar y quieres claridad rápido. ¿Cuál es la mejor apertura?', '["Comentar algo sobre el lugar", "Preguntarle si viene a menudo", "Bromear sobre la gente", "Decirle que querías conocerla"]'::jsonb, 'Ser directo elimina las adivinanzas y va directo a tu intención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6195146-f317-46e7-b387-626cd480fe2b', 'es', 'Discoteca. Música alta. ¿Qué hace que aquí funcione una apertura directa?', '["Decirla con calma y seguridad, sin pedir permiso", "Pedir perdón por interrumpirla a ella y a sus amigas", "Un contacto visual firme y un lenguaje corporal relajado"]'::jsonb, 'Las aperturas directas pierden fuerza cuando vienen con una disculpa en lugar de con seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('587818de-4443-410a-b2e6-4b7c30881359', 'es', '¿Qué significa marcar el tono?', '["Controlar las señales de atracción", "Llevar el tema, el ritmo y la energía", "Adaptarte a su estado de ánimo", "Evitar el rechazo"]'::jsonb, 'Marcar el tono es llevar el momento, no reaccionar a él.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6f2f6f50-a54c-4103-af26-fc4b7d7eb5a0', 'es', 'Te acercas a ella mientras lee un libro. ¿Qué apertura muestra que estás en tu lugar en vez de que te estás metiendo?', '["“Perdón por interrumpir, pero ¿qué estás leyendo?”", "“¿Está bueno ese libro? Estaba pensando en leerlo.”", "“No te quiero molestar, pero tenía que saludarte.”"]'::jsonb, 'Una actitud firme viene de la seguridad, no de pedir permiso; abre sin disculparte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90f24790-0a2d-429f-8aff-e70a5e1589ec', 'es', '¿Qué hace que una apertura sea más interesante que lo que ella estaba haciendo?', '["Es más fuerte, más atrevida o más enérgica que su entorno", "Crea ganchos emocionales como la curiosidad, el juego o sentirse valorada", "Trata temas que le apasionan, según lo que observaste"]'::jsonb, 'Los ganchos emocionales como el juego y la curiosidad hacen atractivo tu planteamiento. El volumen, no.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ecc4789-34ea-4c3f-a98b-9f7ded7e80ca', 'es', '¿Por qué es importante ajustar tu volumen al ambiente?', '["Para no gritar", "Para no tener que repetir", "Para que la interacción fluya sin roces", "Para sonar atractivo"]'::jsonb, 'Cuando el volumen no encaja aparecen roces; ajústalo para que todo sea fácil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e12bb639-9fd1-465e-9e08-5cdeb7ccd65f', 'es', 'Después de tu apertura, ella se inclina y te dice: “Perdón, ¿qué?”. ¿Cuál es la mejor jugada?', '["Repetir la misma frase con el mismo volumen", "Hablar más rápido para terminar la frase", "Acercarte más, metiéndote en su espacio", "Ajustar el volumen y repetirlo con calma"]'::jsonb, 'Ajusta tu volumen al ambiente. Saber leer la situación importa más que el contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e173f101-7036-4046-854b-556473b41c8b', 'es', '¿Qué genera roces en tu forma de hablar?', '["Hablar demasiado bajo para que se te oiga bien en ese ambiente", "Usar un tono de voz grave y resonante", "Atropellar las palabras sin respirar", "No pronunciar las palabras con claridad"]'::jsonb, 'Los roces vienen de no leer bien la situación: ajusta el volumen, respira y habla con claridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3a6aa99-3aa6-471c-b81a-ea31d016cfb1', 'es', '¿Qué comportamiento refleja una apertura genuina a la interacción?', '["Sonreír", "Un tono neutro", "Hacerte preguntas a ti también", "Responder a tus preguntas"]'::jsonb, 'Que te devuelva preguntas indica participación, no solo cortesía; tómalo como luz verde para seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('100aee65-eee7-4907-899a-20d6b97820b1', 'es', '¿Cuál es el propósito principal de leer las primeras señales?', '["Avanzar más rápido", "Evitar el rechazo", "Mantener el respeto", "Impresionarla"]'::jsonb, 'Su comodidad va primero; usa las señales para decidir cuándo seguir y cuándo aflojar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9745631b-e02b-44c5-8703-7cfda0ab734f', 'es', '¿Qué señales suelen indicar cortesía más que receptividad?', '["Sonrisas breves", "Respuestas cortas", "No te hace preguntas", "Deja de hacer lo que estaba haciendo"]'::jsonb, 'La cortesía mantiene la armonía sin invitar a seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1716c8d-11f9-4afa-b80c-5a108dce463e', 'es', 'Cuando no sabes bien cuánto le interesas, ¿cuál es la mejor jugada?', '["Seguir conversando hasta que entre en confianza", "Dar un paso claro que le permita decir sí o no con facilidad", "Hacerle varias preguntas de seguimiento para crear comodidad", "Esperar a que ella avance"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab5203db-096d-46a0-b56b-1b2011ec738e', 'es', '¿Para qué sirve dar un solo paso claro para confirmar su interés en una interacción?', '["Para eliminar la ambigüedad y darle una salida fácil", "Para convencerla de que se interese", "Para acelerar la interacción sin importar su respuesta"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450abadf-8d1e-486e-b76f-6d6eb4d366a0', 'es', 'Después de recibir señales neutras, ¿qué frase ayuda a aclarar su interés?', '["“¿Quieres que tomemos un café otro día?”", "“¿Y a qué te dedicas?”", "“Te dejo seguir con tu día. ¿Tienes Instagram?”", "“Eres un poco difícil de leer.”"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5b86928-0a71-456d-a08d-f5aaaa20bce3', 'es', '¿Qué incluyen normalmente las señales de receptividad?', '["Cuerpo girado hacia ti y una sonrisa genuina", "Te devuelve preguntas y mantiene la conversación", "Respuestas cortas y mirada hacia otro lado", "Se inclina hacia ti o te devuelve la energía"]'::jsonb, 'Una mujer receptiva muestra desde el principio un comportamiento abierto e implicado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3401c3d2-b41a-4191-b69d-0ad4a8292b16', 'es', 'Leer bien las señales ayuda porque:', '["mantiene las interacciones cómodas", "evita la presión", "hace que ella coquetee más", "garantiza la atracción"]'::jsonb, 'Saber leer la situación protege su comodidad, no el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e069eb31-5232-4ac9-b7e0-bd4b26b8bd92', 'es', 'Te da una respuesta breve, vuelve a mirar a otro lado enseguida y tiene el cuerpo girado. ¿Qué señal es?', '["Abierta: es tímida y necesita que insistas con calidez", "Cortés: no está claro; haz un intento más y vuelve a evaluar", "Fría: no está interesada; despídete bien sin insistir"]'::jsonb, 'El lenguaje corporal cerrado pesa más que las respuestas; da un paso atrás y vete con calma.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0251b9d5-9ecf-4f71-aad2-dfc93f31e392', 'es', '¿Qué cualidades hacen que una apertura enganche?', '["Presión", "Curiosidad", "Juego", "Misterio"]'::jsonb, 'Un planteamiento funciona mejor cuando intriga, no cuando exige.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e3aec0-93e1-49e3-8801-5e138b373f07', 'es', '¿Qué hace eficaces a las mejores aperturas indirectas?', '["Dicen explícitamente que te atrae", "Comentan algo del entorno o algo que observaste a tu alrededor", "Se centran solo en su aspecto", "Piden un compromiso pronto"]'::jsonb, 'Un contexto compartido genera comodidad y un flujo natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0601d6e9-3b2f-4dab-8c82-816f101403cc', 'es', '¿Qué señales te indican que sigas construyendo la interacción?', '["Se gira hacia ti, te hace preguntas y mantiene un lenguaje corporal abierto", "Sonríe, te da respuestas largas y muestra reciprocidad", "Ambas son señales de receptividad"]'::jsonb, 'Todas son señales de receptividad: sigue construyendo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('06c68907-301c-447a-b17d-47f93da821ac', 'es', '¿Qué ventaja tiene, con una apertura directa, ponerla de inmediato a evaluarte?', '["Las mujeres respetan a los hombres que son claros con sus intenciones", "Ser directo con seguridad enciende la primera chispa de atracción", "Si le interesas, te ahorras el teatro de ir creando confianza"]'::jsonb, 'Si el interés ya existe, una apertura directa se salta los preámbulos y acelera las cosas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('073d5930-369f-4dd9-9245-c250f26097bc', 'es', '¿Por qué la cortesía se confunde a menudo con receptividad?', '["Suena amistosa", "Oculta la incomodidad", "Es despectiva", "Retrasa el rechazo"]'::jsonb, 'Una respuesta cortés puede ocultar desinterés; fíjate en si hay reciprocidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('08850c3a-5d7f-4d3c-923c-731d1e3f4644', 'es', 'Te dice “sí” con una sonrisa, pero sigue recorriendo el lugar con la mirada mientras hablas. ¿Cómo lo lees?', '["Abierta: si sonríe, le interesas", "Cortés: respetuosa, pero no está presente", "Mixta: distraída, pero con curiosidad", "Fría: mirar alrededor siempre es rechazo"]'::jsonb, 'Una atención dividida indica cortesía, no interés real.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0a2112a8-7aa5-4d33-8a7d-8b46d381ad1c', 'es', 'Te responde con calidez, pero revisa el celular una y otra vez. ¿Qué significa probablemente?', '["Está nerviosa", "Te está poniendo a prueba", "Está ocupada o se está desconectando", "Quiere que insistas"]'::jsonb, 'Participar exige atención; cuando falta, no fuerces las cosas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b567d7e-67fa-4529-a5cb-2a646b501ae0', 'es', 'Ella está con amigas en un bar. ¿Qué determina que una apertura de grupo funcione?', '["Que la apertura sea interesante y pida su opinión", "Que hagas la pregunta con seguridad", "Cómo pasas de la pregunta a una conversación normal"]'::jsonb, 'Asegúrate de que la apertura sea interesante y haga participar al grupo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d78b9e6-8caf-46a0-9c29-39a256ccdd34', 'es', '¿Qué logra realmente ser directo?', '["Demuestra cualidades atractivas", "Genera atracción gracias a la honestidad", "Ella no tiene que descifrar tus intenciones", "No tienes que fingir que estás ahí por otros motivos"]'::jsonb, 'Las aperturas directas eliminan la ambigüedad porque dicen tu intención desde el principio. Ella sabe por qué estás ahí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dca33cf-d79b-4b24-88c0-4b19d5c03b2c', 'es', 'Están los dos en un parque para perros viendo jugar a sus mascotas. ¿Qué apertura quita presión?', '["“Tu perro es muy bonito, como tú.”", "“¿Intercambiamos números?”", "“Los perros son mejores que las personas.”", "“¿De qué raza es el tuyo? El mío siempre tiene demasiada energía.”"]'::jsonb, 'Una experiencia compartida en ese momento inicia la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0e096470-35cf-4e08-bf03-85d6267ab373', 'es', '¿Por qué el dolor del arrepentimiento dura más que el del rechazo?', '["Tu cerebro repasa las oportunidades perdidas durante más tiempo que los rechazos breves", "El rechazo cierra el tema; el arrepentimiento deja preguntas sin respuesta para siempre", "Las dos anteriores"]'::jsonb, 'El rechazo cierra el tema, mientras que el arrepentimiento hace que la mente repase lo que nunca pasó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f4f3084-9f90-4036-ae95-cc8c706eba49', 'es', '¿Por qué pedirle su opinión a alguien engancha más que la charla casual?', '["Las opiniones requieren respuestas más largas", "Las opiniones parecen más inteligentes", "Pedir su opinión indica que valoras su criterio", "Las opiniones se sienten más seguras que los cumplidos"]'::jsonb, 'La gente se ilumina cuando su punto de vista importa. Sentirse valorada genera participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10284be9-9647-41db-8f18-3dfa77d66507', 'es', '¿Adónde deberías mirar mientras te acercas?', '["Un contacto visual breve y casual, sin mirarla fijamente ni clavarle los ojos", "Fijamente a ella, para mostrar una intención y un interés claros", "Un poco más allá de ella, para no parecer demasiado intenso"]'::jsonb, 'Un contacto visual breve comunica que la tienes presente sin presionarla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14546a1d-9532-4604-b285-8494197100dd', 'es', '¿Cuál es el objetivo de pensar bien el ángulo y la distancia al acercarte?', '["Quitar barreras innecesarias para su comodidad", "Mostrar la máxima seguridad estando muy cerca", "Hacer que se sienta un poco amenazada", "Garantizar una atracción inmediata"]'::jsonb, 'Una entrada respetuosa le permite participar sin tener que manejar su incomodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14dc2ce1-631c-4b7a-b151-4c74c34bb2a3', 'es', 'Discoteca. Cruzas miradas con ella desde el otro lado. Ella sonríe. ¿Qué haces?', '["Le devuelves la sonrisa y esperas a ver si se acerca", "Vas hacia ella de inmediato", "Sigues mirándola", "Esperas a que esté en un mejor lugar para acercarte"]'::jsonb, 'En una discoteca se premia la decisión; entra en cuanto se abre la oportunidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('152af858-f915-4ba0-97af-dcd17bde6c3a', 'es', '¿Por qué es importante leer las señales para que ella esté cómoda?', '["Evita que pases límites que ella no ha abierto", "Respetar sus señales demuestra que sabes leer la situación", "Seguir a pesar de señales corteses o frías la incomoda", "Todas las anteriores"]'::jsonb, 'Las señales muestran qué es bienvenido; síguelas para no cruzar límites que ella no ha abierto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16844e95-a04f-4bcf-a8af-c185f70db3c7', 'es', '¿Qué forma de decirla arruina una apertura directa?', '["Un tono tranquilo", "El contacto visual", "Una energía segura", "Una energía de disculpa"]'::jsonb, 'Las aperturas directas pierden fuerza cuando vienen con una disculpa en lugar de con seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('170329e0-190e-459a-8870-3da632ce2a7f', 'es', '¿Qué comportamientos indican que te acercas movido por la curiosidad?', '["Notar detalles y preguntar por ellos", "Disfrutar la conversación sin pensar en lo que sigue", "Llevar la conversación rápido a conseguir su contacto", "Dejar que la interacción se desarrolle sin forzar el rumbo"]'::jsonb, 'La curiosidad se queda en el presente y explora. Una intención oculta salta al resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('18168e30-017b-49fc-8902-92152cce90b8', 'es', 'En una discoteca con mucho ruido, ella te mira un momento y luego se da la vuelta. ¿Qué deberías hacer?', '["Esperar una señal más clara de que le interesas", "Acercarte con buena energía y una sonrisa", "Hablar bajito para no interrumpir a su grupo", "Rendirte y buscar a otra"]'::jsonb, 'De noche se premia actuar rápido y con seguridad antes de que cambie su atención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
